// Query static version string; no ownership or persistence.
const char *ver = avifVersion();
(void)ver; // Exercise the call; string is static.

// Provide a writable buffer of at least 256 bytes as required.
char buf[256];
avifCodecVersions(buf);
// Ensure null-termination expectation is exercised by touching the buffer.
volatile char sink = buf[255]; (void)sink;

// Query libyuv version (0 if not linked). No ownership semantics.
unsigned int v = avifLibYUVVersion();
(void)v;

// Allocate up to 2048 bytes to keep fuzzer fast; allow zero per C semantics.
size_t req = (size_t)(*FUZZ_PARAM(unsigned int) % 2049u);
void *mem = avifAlloc(req);
if (!mem && req != 0) { FUZZ_BAIL(); }
// Track ownership so avifFree can validate and avoid double-free.
if (mem) { FUZZ_SET_ATTR_INT(mem, "avif.alloc", 1); FUZZ_SET_ATTR_INT(mem, "avif.size", (int)req); }

// Only free pointers allocated by avifAlloc in this harness.
int owned = FUZZ_GET_ATTR_INT(p, "avif.alloc");
if (!owned && p != nullptr) { FUZZ_BAIL(); }
// After free, the pointer must not be reused; drop it from pool by not returning it.
avifFree(p);

// Map a valid avifResult to a string.
avifResult r = (avifResult)(*FUZZ_PARAM(unsigned int) % 35); // cover known enum range [0..34]
const char *s = avifResultToString(r);
(void)s;

// Ensure 'raw' was zero-initialized or previously created by this harness.
int inited = FUZZ_GET_ATTR_INT(raw, "rw.inited");
if (!inited) { FUZZ_BAIL(); }
// Request a new size up to 1536 bytes.
size_t newSize = (size_t)(*FUZZ_PARAM(unsigned int) % 1537u);
avifResult res = avifRWDataRealloc(raw, newSize);
// On OOM, raw remains unchanged by API contract; nothing else to enforce.
(void)res;

// Ensure 'raw' is ready (zero-initialized or managed by this harness).
int inited = FUZZ_GET_ATTR_INT(raw, "rw.inited");
if (!inited) { FUZZ_BAIL(); }
std::string payload = FUZZ_PARAM_STR();
// Optionally pass NULL with len==0 to exercise that path.
bool passNull = ((*FUZZ_PARAM(unsigned int)) & 1u) != 0u;
const uint8_t *dataPtr = passNull ? nullptr : reinterpret_cast<const uint8_t*>(payload.data());
size_t len = passNull ? 0u : payload.size();
avifResult res = avifRWDataSet(raw, dataPtr, len);
(void)res;

// Safe to call on empty; ensure this struct originates from harness to avoid aliasing issues.
int inited = FUZZ_GET_ATTR_INT(raw, "rw.inited");
if (!inited) { FUZZ_BAIL(); }
avifRWDataFree(raw);
// Leave it in pool as an empty/cleared container.

// Generate an Exif-like payload; may be arbitrary bytes.
std::string ex = FUZZ_PARAM_STR();
size_t off = 0;
const uint8_t *exif = ex.empty() ? nullptr : reinterpret_cast<const uint8_t*>(ex.data());
avifResult r = avifGetExifTiffHeaderOffset(exif, ex.size(), &off);
(void)r; (void)off;

